class Solution {
public:
    std::vector<int> distinctDifferenceArray(std::vector<int>& nums) {
        int n = nums.size();
        std::vector<int> suffix_distinct(n + 1, 0);
        std::unordered_set<int> seen_suff;
        for (int i = n - 1; i >= 0; i--) {
            seen_suff.insert(nums[i]);
            suffix_distinct[i] = seen_suff.size();
        }
        std::vector<int> ans;
        std::unordered_set<int> seen_pref;
        for (int i = 0; i < n; i++) {
            seen_pref.insert(nums[i]);
            ans.push_back((int)seen_pref.size() - suffix_distinct[i + 1]);
        }
        return ans;
    }
};

class Solution {
    public int[] distinctDifferenceArray(int[] nums) {
        int n = nums.length;
        int[] suffixDistinct = new int[n + 1];
        Set<Integer> seenSuff = new HashSet<>();
        for (int i = n - 1; i >= 0; i--) {
            seenSuff.add(nums[i]);
            suffixDistinct[i] = seenSuff.size();
        }
        int[] ans = new int[n];
        Set<Integer> seenPref = new HashSet<>();
        for (int i = 0; i < n; i++) {
            seenPref.add(nums[i]);
            ans[i] = seenPref.size() - suffixDistinct[i + 1];
        }
        return ans;
    }
}

